import{_ as e,o as t,c as o,a3 as r}from"./chunks/framework.DkWcobGL.js";const u=JSON.parse('{"title":"预览、媒体与地图","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ipad/media.md","filePath":"guide/ipad/media.md"}'),i={name:"guide/ipad/media.md"};function l(n,a,d,s,p,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="预览、媒体与地图" tabindex="-1">预览、媒体与地图 <a class="header-anchor" href="#预览、媒体与地图" aria-label="Permalink to &quot;预览、媒体与地图&quot;">​</a></h1><h2 id="宽屏照片信息与缩放" tabindex="-1">宽屏照片信息与缩放 <a class="header-anchor" href="#宽屏照片信息与缩放" aria-label="Permalink to &quot;宽屏照片信息与缩放&quot;">​</a></h2><p>照片信息和快捷相簿可在照片右侧查看，信息较多时可滚动这一栏。打开单张预览的 <strong>更多操作（…）</strong>，可分别开关 <strong>显示缩略图</strong>、<strong>显示照片信息</strong> 和 <strong>显示快捷相簿</strong>。</p><p>双指捏合或双点缩放，放大后单指拖动查看局部。点一下照片可以显示或隐藏悬浮的整理工具。缩回适合窗口后，继续用手势逐张整理。</p><h2 id="icloud-原图、实况与视频" tabindex="-1">iCloud 原图、实况与视频 <a class="header-anchor" href="#icloud-原图、实况与视频" aria-label="Permalink to &quot;iCloud 原图、实况与视频&quot;">​</a></h2><p>打开只存在 iCloud 的照片时，拾光会下载当前照片并显示圆形进度。失败时先检查网络，再点 <strong>重试</strong>。点播放实况照片也会按需加载动态资源。仅保存在 iCloud 的普通视频，可先到 Apple「照片」打开并下载。</p><h2 id="查看拍摄位置" tabindex="-1">查看拍摄位置 <a class="header-anchor" href="#查看拍摄位置" aria-label="Permalink to &quot;查看拍摄位置&quot;">​</a></h2><ol><li>打开 <strong>显示照片信息</strong>，在右侧信息栏寻找拍摄坐标。</li><li>点坐标进入应用内地图，可拖动、缩放、回到拍摄点。</li><li>根据需要在地图选项切换离线底图，或在 Apple「地图」打开。照片未记录坐标时会显示相应提示。</li></ol>',8)])])}const _=e(i,[["render",l]]);export{u as __pageData,_ as default};
